insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M12602','listening',1,1,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q01A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q01B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q01C.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Сонссон хэллэг «喝牛奶 (hē niúnǎi)» — сүү уух. А зурагт эр хүн аяганд сүү барьж уух гэж байна.',84.96,105.61,'喝牛奶','{"why": "Сонссон хэллэг «喝牛奶 (hē niúnǎi)» — сүү уух. А зурагт эр хүн аяганд сүү барьж уух гэж байна.", "key": "喝牛奶", "keyMn": "Сүү уух", "wrong": {"B": "Эр хүн шилэн аягатай ус ууж байна, сүү биш.", "C": "Эмэгтэй ширээний ард цай уугаад, хажууд нь данх байна — цай уух зураг."}, "tip": "«牛奶 (niúnǎi)» гэдэг үгийг барьж ав: сүү. Цай бол «茶 (chá)».", "words": [{"zh": "喝", "pinyin": "hē", "mn": "уух"}, {"zh": "牛奶", "pinyin": "niúnǎi", "mn": "сүү"}, {"zh": "茶", "pinyin": "chá", "mn": "цай"}], "transcript": [{"zh": "喝牛奶", "pinyin": "hē niúnǎi", "mn": "Сүү уух"}]}'::jsonb),
('M12602','listening',1,2,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q02A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q02B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q02C.webp"}]'::jsonb,'C','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'«坐出租车 (zuò chūzūchē)» — таксинд суух. С зурагт эр хүн «TAXI» бичигтэй таксины суудалд сууж байна.',105.91,126.23,'坐出租车','{"why": "«坐出租车 (zuò chūzūchē)» — таксинд суух. С зурагт эр хүн «TAXI» бичигтэй таксины суудалд сууж байна.", "key": "坐出租车", "keyMn": "Таксинд суух", "wrong": {"A": "Эр хүн явган хүний замаар алхаж байна — алхах зураг.", "B": "Эр хүн онгоцны цонхны дэргэд сууж байна — онгоцоор нисэх зураг."}, "tip": "«坐 (zuò)» нь тээврийн хэрэгсэлд суухыг хэлнэ: 坐飞机, 坐出租车.", "words": [{"zh": "坐", "pinyin": "zuò", "mn": "суух, (унаанд) суух"}, {"zh": "出租车", "pinyin": "chūzūchē", "mn": "такси"}, {"zh": "飞机", "pinyin": "fēijī", "mn": "онгоц"}], "transcript": [{"zh": "坐出租车", "pinyin": "zuò chūzūchē", "mn": "Таксинд суух"}]}'::jsonb),
('M12602','listening',1,3,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q03A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q03B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q03C.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'«三只猫 (sān zhī māo)» — гурван муур. А зурагт гурван муур байна.',126.53,147.05,'三只猫','{"why": "«三只猫 (sān zhī māo)» — гурван муур. А зурагт гурван муур байна.", "key": "三只猫", "keyMn": "Гурван муур", "wrong": {"B": "Гурван нохой байна (том шар нохой, жижиг хар цагаан нохой, хаски) — муур биш.", "C": "Аяганд гурван өндөг байна — «三个鸡蛋» гэх зураг."}, "trap": "Тоо нь гурав байх тул В, С мөн гурав — харин амьтны төрлийг «猫 (māo)» гэж сонсох хэрэгтэй.", "words": [{"zh": "三", "pinyin": "sān", "mn": "гурав"}, {"zh": "只", "pinyin": "zhī", "mn": "(амьтны) тоолуур үг"}, {"zh": "猫", "pinyin": "māo", "mn": "муур"}], "transcript": [{"zh": "三只猫", "pinyin": "sān zhī māo", "mn": "Гурван муур"}]}'::jsonb),
('M12602','listening',1,4,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q04A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q04B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q04C.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'«在书店看书 (zài shūdiàn kàn shū)» — номын дэлгүүрт ном унших. А зурагт охин номын тавиурын дунд ном уншиж байна.',147.35,169.98,'在书店看书','{"why": "«在书店看书 (zài shūdiàn kàn shū)» — номын дэлгүүрт ном унших. А зурагт охин номын тавиурын дунд ном уншиж байна.", "key": "在书店看书", "keyMn": "Номын дэлгүүрт ном унших", "wrong": {"B": "Залуу ширээний ард хоол идэж байна.", "C": "Хүн орон дээр унтаж байна."}, "tip": "«在 + газар + үйлдэл» бүтэц: 在书店看书.", "words": [{"zh": "书店", "pinyin": "shūdiàn", "mn": "номын дэлгүүр"}, {"zh": "看书", "pinyin": "kàn shū", "mn": "ном унших"}, {"zh": "在", "pinyin": "zài", "mn": "-д, -т (байршил)"}], "transcript": [{"zh": "在书店看书", "pinyin": "zài shūdiàn kàn shū", "mn": "Номын дэлгүүрт ном унших"}]}'::jsonb),
('M12602','listening',1,5,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q05A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q05B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q05C.webp"}]'::jsonb,'B','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'«漂亮的汉字 (piàoliang de Hànzì)» — гоё ханз. В зурагт торлосон цаасан дээр гоё бичсэн ханзан шүлэг байна.',170.28,192.11,'漂亮的汉字','{"why": "«漂亮的汉字 (piàoliang de Hànzì)» — гоё ханз. В зурагт торлосон цаасан дээр гоё бичсэн ханзан шүлэг байна.", "key": "漂亮的汉字", "keyMn": "Гоё ханз", "wrong": {"A": "Өлгүүр дээр өлгөсөн хүрэм байна — «漂亮的衣服» (гоё хувцас) гэх зураг.", "C": "Цастай ой, мөстэй гол — өвлийн байгаль."}, "tip": "«漂亮的 + нэр үг» — «гоё ...». Энд нэр үг нь 汉字.", "words": [{"zh": "漂亮", "pinyin": "piàoliang", "mn": "гоё, үзэсгэлэнтэй"}, {"zh": "汉字", "pinyin": "Hànzì", "mn": "ханз"}], "transcript": [{"zh": "漂亮的汉字", "pinyin": "piàoliang de Hànzì", "mn": "Гоё ханз"}]}'::jsonb),
('M12602','listening',2,6,'choice','','[{"key": "A", "text": "没关系"}, {"key": "B", "text": "很喜欢"}, {"key": "C", "text": "不好吃"}]'::jsonb,'B','auto',1,'/mock-tests/m12602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'«你喜欢吃饺子吗？(Nǐ xǐhuan chī jiǎozi ma?)» гэж «чамд зөөтэй бууз таалагддаг уу?» гэж асуужээ. «很喜欢 (hěn xǐhuan)» — «их таалагддаг» гэсэн шууд хариу.',234.23,250.28,'你喜欢吃饺子吗？','{"why": "«你喜欢吃饺子吗？(Nǐ xǐhuan chī jiǎozi ma?)» гэж «чамд зөөтэй бууз таалагддаг уу?» гэж асуужээ. «很喜欢 (hěn xǐhuan)» — «их таалагддаг» гэсэн шууд хариу.", "key": "很喜欢", "keyMn": "Их дуртай", "wrong": {"A": "«没关系 (méi guānxi)» — зүгээр ээ, уучлал гуйсанд хариулна.", "C": "«不好吃 (bù hǎochī)» — амттай биш; «喜欢» гэж асуусанд тохирохгүй."}, "tip": "«喜欢 (xǐhuan)» гэж асуувал «喜欢/不喜欢»-аар хариулна.", "words": [{"zh": "饺子", "pinyin": "jiǎozi", "mn": "цзяоцзы (хятад зөөтэй бууз)"}, {"zh": "喜欢", "pinyin": "xǐhuan", "mn": "дуртай"}, {"zh": "好吃", "pinyin": "hǎochī", "mn": "амттай"}], "transcript": [{"zh": "你喜欢吃饺子吗？", "pinyin": "Nǐ xǐhuan chī jiǎozi ma?", "mn": "Чи зөөтэй бууз (цзяоцзы) идэх дуртай юу?"}]}'::jsonb),
('M12602','listening',2,7,'choice','','[{"key": "A", "text": "谢谢"}, {"key": "B", "text": "很好听"}, {"key": "C", "text": "会一点儿"}]'::jsonb,'C','auto',1,'/mock-tests/m12602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'«您会说中文吗？(Nín huì shuō Zhōngwén ma?)» — «Та хятадаар ярьж чадах уу?» «会一点儿 (huì yìdiǎnr)» — «жаахан чадна» гэдэг нь «会» гэсэн асуултад тохирсон хариу.',250.58,276.82,'先生，请问您会说中文吗？','{"why": "«您会说中文吗？(Nín huì shuō Zhōngwén ma?)» — «Та хятадаар ярьж чадах уу?» «会一点儿 (huì yìdiǎnr)» — «жаахан чадна» гэдэг нь «会» гэсэн асуултад тохирсон хариу.", "key": "会一点儿", "keyMn": "Жаахан чадна", "wrong": {"A": "«谢谢 (xièxie)» — баярлалаа, чадах эсэхийг асуусанд хариу биш.", "B": "«很好听 (hěn hǎotīng)» — сонсоход сайхан; хэл чадах эсэхтэй холбоогүй."}, "tip": "«会 (huì)» нь сурч чаддаг чадварыг хэлнэ.", "words": [{"zh": "会", "pinyin": "huì", "mn": "чадах"}, {"zh": "说", "pinyin": "shuō", "mn": "ярих"}, {"zh": "中文", "pinyin": "Zhōngwén", "mn": "хятад хэл"}, {"zh": "一点儿", "pinyin": "yìdiǎnr", "mn": "жаахан"}], "transcript": [{"zh": "先生，请问您会说中文吗？", "pinyin": "Xiānsheng, qǐngwèn nín huì shuō Zhōngwén ma?", "mn": "Эрхэм ээ, та хятадаар ярьж чадах уу?"}]}'::jsonb),
('M12602','listening',2,8,'choice','','[{"key": "A", "text": "十分钟"}, {"key": "B", "text": "八点半"}, {"key": "C", "text": "三个小时"}]'::jsonb,'B','auto',1,'/mock-tests/m12602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'«几点 (jǐ diǎn)» — «хэдэн цагт» гэж цаг асуусан. Цагаар хариулсан «八点半 (bā diǎn bàn)» — найман цаг гучин минут.',277.12,302.18,'你每天早上几点起床？','{"why": "«几点 (jǐ diǎn)» — «хэдэн цагт» гэж цаг асуусан. Цагаар хариулсан «八点半 (bā diǎn bàn)» — найман цаг гучин минут.", "key": "八点半", "keyMn": "Найман цаг хагас", "wrong": {"A": "«十分钟 (shí fēnzhōng)» — арван минутын үргэлжлэх хугацаа, цаг биш.", "C": "«三个小时 (sān ge xiǎoshí)» — гурван цагийн хугацаа, цагийн агшин биш."}, "trap": "«几点» бол цагийн агшин, «多长时间» бол үргэлжлэх хугацаа. Хугацаагаар хариулсан А, С-д битгий хуурагд.", "words": [{"zh": "几点", "pinyin": "jǐ diǎn", "mn": "хэдэн цаг"}, {"zh": "起床", "pinyin": "qǐchuáng", "mn": "босох"}, {"zh": "半", "pinyin": "bàn", "mn": "хагас"}, {"zh": "早上", "pinyin": "zǎoshang", "mn": "өглөө"}], "transcript": [{"zh": "你每天早上几点起床？", "pinyin": "Nǐ měitiān zǎoshang jǐ diǎn qǐchuáng?", "mn": "Чи өдөр бүр өглөө хэдэн цагт босдог вэ?"}]}'::jsonb),
('M12602','listening',2,9,'choice','','[{"key": "A", "text": "商店"}, {"key": "B", "text": "衣服"}, {"key": "C", "text": "睡觉"}]'::jsonb,'A','auto',1,'/mock-tests/m12602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'«去哪儿 (qù nǎr)» — хаашаа явсан бэ гэж асуусан. «买东西 (mǎi dōngxi)» буюу юм авахаар очдог газар нь «商店 (shāngdiàn)» — дэлгүүр.',302.48,335.16,'哥哥去哪儿买东西了？','{"why": "«去哪儿 (qù nǎr)» — хаашаа явсан бэ гэж асуусан. «买东西 (mǎi dōngxi)» буюу юм авахаар очдог газар нь «商店 (shāngdiàn)» — дэлгүүр.", "key": "商店", "keyMn": "Дэлгүүр", "wrong": {"B": "«衣服 (yīfu)» — хувцас; бараа, газар биш.", "C": "«睡觉 (shuìjiào)» — унтах; үйлдэл, газар биш."}, "tip": "«哪儿 (nǎr)» гэж асуувал газрын нэрээр хариулна.", "words": [{"zh": "哥哥", "pinyin": "gēge", "mn": "ах"}, {"zh": "哪儿", "pinyin": "nǎr", "mn": "хаана, хаашаа"}, {"zh": "买东西", "pinyin": "mǎi dōngxi", "mn": "юм авах"}, {"zh": "商店", "pinyin": "shāngdiàn", "mn": "дэлгүүр"}], "transcript": [{"zh": "哥哥去哪儿买东西了？", "pinyin": "Gēge qù nǎr mǎi dōngxi le?", "mn": "Ах хаашаа юм авахаар явсан бэ?"}]}'::jsonb),
('M12602','listening',2,10,'choice','','[{"key": "A", "text": "两岁"}, {"key": "B", "text": "很漂亮"}, {"key": "C", "text": "是学生"}]'::jsonb,'A','auto',1,'/mock-tests/m12602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'«多大 (duō dà)» — хэдэн настай вэ гэж асуусан. «两岁 (liǎng suì)» — хоёр настай гэж насаар хариулсан.',335.46,351.93,'你妹妹今年多大了？','{"why": "«多大 (duō dà)» — хэдэн настай вэ гэж асуусан. «两岁 (liǎng suì)» — хоёр настай гэж насаар хариулсан.", "key": "两岁", "keyMn": "Хоёр настай", "wrong": {"B": "«很漂亮 (hěn piàoliang)» — гоё; төрх байдал, нас биш.", "C": "«是学生 (shì xuésheng)» — сурагч; мэргэжлийн хариулт, нас биш."}, "tip": "«多大» = нас асуух. Хариу нь «…岁».", "words": [{"zh": "妹妹", "pinyin": "mèimei", "mn": "дүү охин"}, {"zh": "今年", "pinyin": "jīnnián", "mn": "энэ жил"}, {"zh": "多大", "pinyin": "duō dà", "mn": "хэдтэй, хэдэн настай"}, {"zh": "岁", "pinyin": "suì", "mn": "нас"}], "transcript": [{"zh": "你妹妹今年多大了？", "pinyin": "Nǐ mèimei jīnnián duō dà le?", "mn": "Чиний дүү охин энэ жил хэдтэй вэ?"}]}'::jsonb),
('M12602','listening',3,11,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q11A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q11B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q11C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m12602/img/q11D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m12602/img/q11E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m12602/img/q11F.webp"}]'::jsonb,'F','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Эмэгтэй «谢谢你给我面包！» гэж талархсан. F зурагт эр хүн эмэгтэйд юм (талх) барьж өгч байна.',392.16,423.94,'女：谢谢你给我面包！
男：不客气。多吃点儿。','{"why": "Эмэгтэй «谢谢你给我面包！» гэж талархсан. F зурагт эр хүн эмэгтэйд юм (талх) барьж өгч байна.", "key": "谢谢你给我面包", "keyMn": "Талх өгсөнд баярлалаа", "wrong": {"A": "Охин тоглоомон баавгайн дунд тоглож байна — яриатай холбоогүй.", "B": "Хоёр хүн хүйтэнд борооны дунд гүйж байна.", "C": "Хоёр хүн гар барьж мэндэлж байна.", "D": "Найз нар хамт ширээнд хооллож байна.", "E": "Ширээн дээр гар утас байна."}, "tip": "«给 (gěi)» — өгөх: зураг дээр юм дамжуулж байгааг хайгаарай.", "words": [{"zh": "谢谢", "pinyin": "xièxie", "mn": "баярлалаа"}, {"zh": "给", "pinyin": "gěi", "mn": "өгөх"}, {"zh": "面包", "pinyin": "miànbāo", "mn": "талх"}, {"zh": "不客气", "pinyin": "bú kèqi", "mn": "зүгээр, дэмий"}], "transcript": [{"zh": "女：谢谢你给我面包！", "pinyin": "nǚ: Xièxie nǐ gěi wǒ miànbāo!", "mn": "Эм: Талх өгсөнд баярлалаа!"}, {"zh": "男：不客气。多吃点儿。", "pinyin": "nán: Bú kèqi. Duō chī diǎnr.", "mn": "Эр: Зүгээр дээ. Илүү идээрэй."}]}'::jsonb),
('M12602','listening',3,12,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q11A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q11B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q11C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m12602/img/q11D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m12602/img/q11E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m12602/img/q11F.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'«你看见女儿了吗？» — охиноо харсан уу гэж асуухад «在那儿呢» гэж хариулав. А зурагт жижиг охин тоглоомон баавгайнуудын дунд тоглож байна.',424.24,464.65,'男：你看见女儿了吗？
女：在那儿呢。','{"why": "«你看见女儿了吗？» — охиноо харсан уу гэж асуухад «在那儿呢» гэж хариулав. А зурагт жижиг охин тоглоомон баавгайнуудын дунд тоглож байна.", "key": "女儿", "keyMn": "охин (хүүхэд)", "wrong": {"B": "Хоёр том хүн хүйтэнд борооны дунд гүйж байна.", "C": "Хоёр том хүн гар барьж байна.", "D": "Том хүмүүс ширээнд хооллож байна.", "E": "Ширээн дээр гар утас байна.", "F": "Залуу эмэгтэйд юм барьж өгч байна."}, "trap": "«女儿 (nǚ''ér)» — охин (хүүхэд), «女人» биш. Зураг дээрх цорын ганц бяцхан хүүхдийг сонго.", "words": [{"zh": "女儿", "pinyin": "nǚ''ér", "mn": "охин (хүү/охин хүүхэд)"}, {"zh": "看见", "pinyin": "kànjiàn", "mn": "харах, олж харах"}, {"zh": "那儿", "pinyin": "nàr", "mn": "тэнд"}], "transcript": [{"zh": "男：你看见女儿了吗？", "pinyin": "nán: Nǐ kànjiàn nǚ''ér le ma?", "mn": "Эр: Чи охиныг харсан уу?"}, {"zh": "女：在那儿呢。", "pinyin": "nǚ: Zài nàr ne.", "mn": "Эм: Тэнд байна шүү."}]}'::jsonb),
('M12602','listening',3,13,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q11A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q11B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q11C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m12602/img/q11D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m12602/img/q11E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m12602/img/q11F.webp"}]'::jsonb,'B','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'«天气怎么样？» — цаг агаар ямар байна гэхэд «很冷，还下雨了» — хүйтэн бөгөөд бороо орж байна. В зурагт хоёр хүн зузаан хувцастай, халхавчтай хүн цаана байгаа борооны өдөр.',464.95,486.04,'女：外边天气怎么样？
男：很冷，还下雨了。','{"why": "«天气怎么样？» — цаг агаар ямар байна гэхэд «很冷，还下雨了» — хүйтэн бөгөөд бороо орж байна. В зурагт хоёр хүн зузаан хувцастай, халхавчтай хүн цаана байгаа борооны өдөр.", "key": "很冷，还下雨了", "keyMn": "Их хүйтэн, бороо орж байна", "wrong": {"A": "Охин нарлаг талбайд тоглож байна.", "C": "Хоёр хүн гар барьж байна.", "D": "Найз нар дотор хооллож байна.", "E": "Ширээн дээр гар утас байна.", "F": "Залуу эмэгтэйд юм барьж өгч байна."}, "words": [{"zh": "天气", "pinyin": "tiānqì", "mn": "цаг агаар"}, {"zh": "冷", "pinyin": "lěng", "mn": "хүйтэн"}, {"zh": "下雨", "pinyin": "xià yǔ", "mn": "бороо орох"}, {"zh": "外边", "pinyin": "wàibian", "mn": "гадаа"}], "transcript": [{"zh": "女：外边天气怎么样？", "pinyin": "nǚ: Wàibian tiānqì zěnmeyàng?", "mn": "Эм: Гадаа цаг агаар ямар байна?"}, {"zh": "男：很冷，还下雨了。", "pinyin": "nán: Hěn lěng, hái xià yǔ le.", "mn": "Эр: Их хүйтэн, бас бороо орлоо."}]}'::jsonb),
('M12602','listening',3,14,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12602/img/q11A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12602/img/q11B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12602/img/q11C.webp"}, {"key": "D", "text": "", "image_url": "/mock-tests/m12602/img/q11D.webp"}, {"key": "E", "text": "", "image_url": "/mock-tests/m12602/img/q11E.webp"}, {"key": "F", "text": "", "image_url": "/mock-tests/m12602/img/q11F.webp"}]'::jsonb,'D','auto',1,'/mock-tests/m12602/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Эмэгтэй «我去和朋友吃饭» — найзтайгаа хоол идэхээр явна гэсэн. D зурагт хэдэн найз ширээнд хооллож байна.',486.34,518.89,'男：你晚上要做什么？
女：我去和朋友吃饭。','{"why": "Эмэгтэй «我去和朋友吃饭» — найзтайгаа хоол идэхээр явна гэсэн. D зурагт хэдэн найз ширээнд хооллож байна.", "key": "我去和朋友吃饭", "keyMn": "Би найзтайгаа хооллохоор явна", "wrong": {"A": "Охин ганцаараа тоглоомон баавгайтай тоглож байна.", "B": "Хоёр хүн борооны дунд гүйж байна.", "C": "Хоёр хүн гар барьж мэндэлж байна.", "E": "Ширээн дээр гар утас байна.", "F": "Залуу эмэгтэйд юм барьж өгч байна."}, "tip": "«和 (hé) + хүн» — «хэн нэгэнтэй хамт». Зураг дээрх олуулаа хооллож буйг ол.", "words": [{"zh": "晚上", "pinyin": "wǎnshang", "mn": "орой"}, {"zh": "朋友", "pinyin": "péngyou", "mn": "найз"}, {"zh": "和", "pinyin": "hé", "mn": "-тай, хамт"}, {"zh": "吃饭", "pinyin": "chīfàn", "mn": "хоол идэх"}], "transcript": [{"zh": "男：你晚上要做什么？", "pinyin": "nán: Nǐ wǎnshang yào zuò shénme?", "mn": "Эр: Чи орой юу хийх вэ?"}, {"zh": "女：我去和朋友吃饭。", "pinyin": "nǚ: Wǒ qù hé péngyou chīfàn.", "mn": "Эм: Би найзуудтайгаа хооллохоор явна."}]}'::jsonb),
