('M12602','reading',2,26,'match','你们公司有多少人？','[{"key": "A", "text": "下了，雪不大。"}, {"key": "B", "text": "坐吧，没人。"}, {"key": "C", "text": "一杯牛奶吧。"}, {"key": "D", "text": "没有，怎么了？"}, {"key": "E", "text": "一百五十个。"}, {"key": "F", "text": "好的，谢谢！"}]'::jsonb,'E','auto',1,null,null,false,array['sk.reading.match','voc.hsk1','hsk30']::text[],'«多少人 (duōshao rén)» — хэдэн хүн вэ гэж тоо асуусан. «一百五十个 (yìbǎi wǔshí ge)» — зуун тавин (хүн) гэж тоогоор хариулсан.',null,null,null,'{"why": "«多少人 (duōshao rén)» — хэдэн хүн вэ гэж тоо асуусан. «一百五十个 (yìbǎi wǔshí ge)» — зуун тавин (хүн) гэж тоогоор хариулсан.", "key": "一百五十个", "keyMn": "Зуун тавь", "wrong": {"A": "Цас орсон эсэхийн хариулт.", "B": "Суудлаа санал болгосон хариулт.", "C": "Юу уухыг хэлсэн хариулт.", "D": "Утасдсан эсэхийн хариулт.", "F": "Санал, урилгад зөвшөөрсөн хариулт."}, "tip": "«多少 (duōshao)» гэвэл тоогоор хариулна.", "words": [{"zh": "公司", "pinyin": "gōngsī", "mn": "компани"}, {"zh": "多少", "pinyin": "duōshao", "mn": "хэд, хэдэн"}, {"zh": "一百", "pinyin": "yìbǎi", "mn": "зуу"}]}'::jsonb),
('M12602','reading',2,27,'match','你们那儿下雪了吗？','[{"key": "A", "text": "下了，雪不大。"}, {"key": "B", "text": "坐吧，没人。"}, {"key": "C", "text": "一杯牛奶吧。"}, {"key": "D", "text": "没有，怎么了？"}, {"key": "E", "text": "一百五十个。"}, {"key": "F", "text": "好的，谢谢！"}]'::jsonb,'A','auto',1,null,null,false,array['sk.reading.match','voc.hsk1','hsk30']::text[],'«下雪了吗？» — цас орсон уу гэж асуусан. «下了，雪不大» — «Орсон, цас их биш» гэж хариулсан.',null,null,null,'{"why": "«下雪了吗？» — цас орсон уу гэж асуусан. «下了，雪不大» — «Орсон, цас их биш» гэж хариулсан.", "key": "下了，雪不大", "keyMn": "Орсон, цас их биш", "wrong": {"B": "«坐吧» — суу гэсэн, цасны тухай биш.", "C": "«一杯牛奶» — уух юмны хариулт.", "D": "«没有，怎么了？» — «Үгүй» гэж хариулж болох ч «怎么了» нэмж байгаа нь цасны асуултад зохихгүй.", "E": "Тоо хэлсэн хариулт.", "F": "Талархал/зөвшөөрлийн хариулт."}, "trap": "«了» дээр суурилсан асуултад «下了/没下» гэж давтаж хариулна.", "words": [{"zh": "下雪", "pinyin": "xià xuě", "mn": "цас орох"}, {"zh": "那儿", "pinyin": "nàr", "mn": "тэнд"}, {"zh": "不大", "pinyin": "bú dà", "mn": "их биш"}]}'::jsonb),
('M12602','reading',2,28,'match','老师给你打电话了吗？','[{"key": "A", "text": "下了，雪不大。"}, {"key": "B", "text": "坐吧，没人。"}, {"key": "C", "text": "一杯牛奶吧。"}, {"key": "D", "text": "没有，怎么了？"}, {"key": "E", "text": "一百五十个。"}, {"key": "F", "text": "好的，谢谢！"}]'::jsonb,'D','auto',1,null,null,false,array['sk.reading.match','voc.hsk1','hsk30']::text[],'«老师给你打电话了吗？» гэж асуухад «没有，怎么了？» — «Үгүй, юу болсон юм бэ?» гэж хариулсан. Энэ нь «了 + 吗» асуултын «没有» хариу.',null,null,null,'{"why": "«老师给你打电话了吗？» гэж асуухад «没有，怎么了？» — «Үгүй, юу болсон юм бэ?» гэж хариулсан. Энэ нь «了 + 吗» асуултын «没有» хариу.", "key": "没有，怎么了？", "keyMn": "Үгүй, юу болсон юм?", "wrong": {"A": "Цасны тухай хариулт.", "B": "Суудлын тухай хариулт.", "C": "Юу уухын тухай хариулт.", "E": "Тоо хэлсэн хариулт.", "F": "«好的，谢谢» — зөвшөөрч талархсан хариулт."}, "tip": "«有没有 / ...了吗» асуултад «没有» гэж хариулж болно.", "words": [{"zh": "老师", "pinyin": "lǎoshī", "mn": "багш"}, {"zh": "打电话", "pinyin": "dǎ diànhuà", "mn": "утсаар ярих"}, {"zh": "怎么了", "pinyin": "zěnme le", "mn": "юу болсон бэ"}]}'::jsonb),
